"""
Crouton Alpha Agent - 可运行的 Agent 模板

功能:
1. 离线演示模式: 无需 API Key, 输入命令即可体验工具调用循环
2. LLM 模式: 配置 OPENAI_API_KEY 或兼容 API 后, 用大模型决策
3. 内置工具: calculator / current_time / file_read / echo

运行:
    python agent.py                 # 交互模式
    python agent.py "1+2*3"       # 单次问答
    python agent.py --demo          # 演示模式
"""

from __future__ import annotations

import os
import re
import sys
from datetime import datetime
from typing import Callable, Dict, Any


# ---------- 工具定义 ----------
def tool_calculator(expression: str) -> str:
    """计算数学表达式, 例如: 1+2*3"""
    # 安全过滤: 只允许数字、运算符、括号、点、空格
    if not re.fullmatch(r"[0-9+\-*/(). %]+", expression):
        return "错误: 表达式包含非法字符, 只支持 + - * / ( ) . %"
    try:
        result = eval(expression, {"__builtins__": {}}, {})  # 小心: 模板示例, 生产环境请换 AST 解析
        return f"{expression} = {result}"
    except Exception as e:
        return f"计算错误: {e}"


def tool_current_time(_: str = "") -> str:
    return datetime.now().strftime("%Y-%m-%d %H:%M:%S")


def tool_file_read(path: str) -> str:
    try:
        with open(path, encoding="utf-8") as f:
            return f.read()[:2000]
    except Exception as e:
        return f"读取失败: {e}"


def tool_echo(text: str) -> str:
    return text


TOOLS: Dict[str, Callable[[str], str]] = {
    "calculator": tool_calculator,
    "current_time": tool_current_time,
    "file_read": tool_file_read,
    "echo": tool_echo,
}

TOOL_DESCRIPTIONS = {
    "calculator": "计算数学表达式, 参数: expression, 例: calculator(1+2*3)",
    "current_time": "获取当前时间, 无需参数",
    "file_read": "读取文本文件, 参数: path, 例: file_read(docs/README.md)",
    "echo": "原样返回文本",
}


def run_tool(name: str, arg: str) -> str:
    fn = TOOLS.get(name)
    if fn is None:
        return f"未知工具: {name}, 可用工具: {', '.join(TOOLS)}"
    return fn(arg)


# ---------- Agent 核心 ----------
class Agent:
    def __init__(self, name: str = "Crouton Alpha Agent"):
        self.name = name
        self.history: list[Dict[str, str]] = []

    def step_offline(self, user_input: str) -> str:
        """离线规则决策: 识别意图 -> 调用工具 -> 返回结果"""
        self.history.append({"role": "user", "content": user_input})
        text = user_input.strip()
        low = text.lower()

        # 规则 1: 时间
        if any(k in low for k in ["时间", "几点", "date", "time", "now"]):
            result = run_tool("current_time", "")
            reply = f"当前时间是: {result}"

        # 规则 2: 计算 / 工具调用 calculator(...)
        m = re.search(r"calculator\s*\(\s*(.+?)\s*\)", text, re.I)
        if m:
            reply = run_tool("calculator", m.group(1))
        elif re.fullmatch(r"[0-9+\-*/(). %]+", text) and any(c in text for c in "+-*/"):
            reply = run_tool("calculator", text)

        # 规则 3: 读取文件 file_read(...)
        elif m2 := re.search(r"file_read\s*\(\s*(.+?)\s*\)", text, re.I):
            reply = run_tool("file_read", m2.group(1))

        # 规则 4: echo(...)
        elif m3 := re.search(r"echo\s*\(\s*(.+?)\s*\)", text, re.I):
            reply = run_tool("echo", m3.group(1))

        else:
            reply = (
                "你好！我是 Agent 演示模式。我能做：\n"
                "  - 计算: 直接输入 1+2*3，或 calculator(1+2*3)\n"
                "  - 查时间: 输入 现在几点 / time\n"
                "  - 读文件: file_read(docs/README.md)\n"
                "  - 回显: echo(hello)\n"
                "  - 帮助: help"
            )
            if low == "help":
                reply = "可用工具:\n" + "\n".join(
                    f"  - {k}: {v}" for k, v in TOOL_DESCRIPTIONS.items()
                )

        self.history.append({"role": "assistant", "content": reply})
        return reply

    def run(self, user_input: str) -> str:
        # 有 LLM 配置时走 LLM 模式, 否则走离线模式
        if os.environ.get("OPENAI_API_KEY"):
            try:
                return self._run_llm(user_input)
            except Exception as e:
                return f"LLM 调用失败, 已回退到离线模式: {e}\n\n" + self.step_offline(user_input)
        return self.step_offline(user_input)

    def _run_llm(self, user_input: str) -> str:
        # 避免硬依赖, 按需导入
        from openai import OpenAI  # pip install openai

        client = OpenAI(
            api_key=os.environ["OPENAI_API_KEY"],
            base_url=os.environ.get("OPENAI_BASE_URL", "https://api.openai.com/v1"),
        )
        model = os.environ.get("OPENAI_MODEL", "gpt-4o-mini")
        system = (
            "你是 Crouton Alpha Agent. 可用工具:\n"
            + "\n".join(f"- {k}: {v}" for k, v in TOOL_DESCRIPTIONS.items())
            + "\n需要工具时, 只输出一行: TOOL:name:arg\n不需要工具时直接回答。"
        )
        messages = [{"role": "system", "content": system},
                    {"role": "user", "content": user_input}]
        resp = client.chat.completions.create(model=model, messages=messages)
        content = resp.choices[0].message.content.strip()

        m = re.match(r"TOOL:(\w+):?(.*)", content)
        if m:
            tool_result = run_tool(m.group(1), m.group(2))
            messages.append({"role": "assistant", "content": content})
            messages.append({"role": "user", "content": f"工具结果: {tool_result}\n请基于结果给最终答复。"})
            resp2 = client.chat.completions.create(model=model, messages=messages)
            return resp2.choices[0].message.content.strip()
        return content


def demo():
    agent = Agent()
    cases = ["1+2*3", "现在几点", "file_read(docs/README.md)", "echo(hello agent)", "help"]
    for c in cases:
        print(f"\n>>> {c}")
        print(agent.run(c))


def main():
    agent = Agent()
    if "--demo" in sys.argv:
        demo()
        return
    if len(sys.argv) > 1:
        print(agent.run(" ".join(sys.argv[1:])))
        return
    print(f"{agent.name} 已启动, 输入 help 查看帮助, Ctrl+C 退出")
    try:
        while True:
            user = input("\n>>> ").strip()
            if not user:
                continue
            if user.lower() in ("exit", "quit"):
                break
            print(agent.run(user))
    except KeyboardInterrupt:
        print("\n再见!")


if __name__ == "__main__":
    main()

